exercises.starter_code:
#include <stdio.h>

int main(void) {
    int day = 2;
    // switch (day) ...
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    int day = 2;
    switch (day) {
    case 1: puts("Monday"); break;
    case 2: puts("Tuesday"); break;
    case 3: puts("Wednesday"); break;
    default: puts("Unknown"); break;
    }
    return 0;
}

exercises.starter_code:
#include <stdio.h>

int main(void) {
    const char *colors[] = {"red", "green", "blue"};
    // for ...
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <stddef.h>

int main(void) {
    const char *colors[] = {"red", "green", "blue"};
    for (size_t i = 0; i < 3; i++) printf("%s\n", colors[i]);
    return 0;
}

exercises.starter_code:
