int main(void) {
    int score = 85;
    // print grade
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    int score = 85;
    if (score >= 90) puts("A");
    else if (score >= 80) puts("B");
    else if (score >= 70) puts("C");
    else if (score >= 60) puts("D");
    else puts("F");
    return 0;
}

exercises.starter_code:
#include <stdio.h>

int main(void) {
    int i = 1;
    for (;;) { /* break at 5 */ }
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    int i = 1;
    for (;;) {
        if (i >= 5) break;
        printf("%d\n", i);
        i++;
    }
    return 0;
}

exercises.starter_code:
#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 10; i++) { /* continue on even */ }
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 10; i++) {
        if (i % 2 == 0) continue;
        printf("%d\n", i);
    }
    return 0;
}
